export const load = () => ({
  people: [
    { id: 1, name: 'Ada Lovelace', team: 'Platform' },
    { id: 2, name: 'Grace Hopper', team: 'Compilers' },
    { id: 3, name: 'Alan Turing', team: 'Research' }
  ]
});

