  export let data: PageData;
</script>

<h1>Team directory</h1>
<ul>
  {#each data.people as person (person.id)}
    <li>{person.name} — {person.team}</li>
  {/each}
</ul>

input.new_string:
  export let data: PageData;

  let query = '';
  $: needle = query.trim().toLowerCase();
  $: filtered = data.people.filter((p) => p.name.toLowerCase().includes(needle));
</script>

<h1>Team directory</h1>
<input type="search" placeholder="Search by name" aria-label="Search people by name" bind:value={query} />
<ul>
  {#each filtered as person (person.id)}
    <li>{person.name} — {person.team}</li>
  {:else}
    <li>No matches</li>
  {/each}
</ul>

